import math

class RetrievalEvaluator:
    def reciprocal_rank(self, ranked_docs: list[str], relevant_set: set) -> float:
        for i, doc in enumerate(ranked_docs):
            if doc in relevant_set:
                return 1.0 / (i + 1)
        return 0.0

    def dcg_at_k(self, relevance_scores: list[int], k: int) -> float:
        total = 0.0
        for i, rel in enumerate(relevance_scores[:k]):
            total += rel / math.log2(i + 2)
        return total

    def ndcg_at_k(self, relevance_scores: list[int], k: int) -> float:
        ideal = self.dcg_at_k(sorted(relevance_scores, reverse=True), k)
        if ideal == 0:
            return 0.0
        return self.dcg_at_k(relevance_scores, k) / ideal

    def mrr(self, all_ranked: list[list[str]], all_relevant: list[set]) -> float:
        if not all_ranked:
            return 0.0
        rrs = [self.reciprocal_rank(r, s) for r, s in zip(all_ranked, all_relevant)]
        return sum(rrs) / len(rrs)

# Test it:
ev = RetrievalEvaluator()

# Reciprocal rank
print(ev.reciprocal_rank(["a", "b", "c"], {"b", "c"}))
print(ev.reciprocal_rank(["x", "y"], {"z"}))

# NDCG
print(f"{ev.ndcg_at_k([3, 2, 0, 0], k=3):.4f}")
print(f"{ev.ndcg_at_k([0, 0, 3, 2], k=3):.4f}")

# MRR
result = ev.mrr(
    [["a", "b", "c"], ["x", "y", "z"]],
    [{"b"}, {"x"}]
)
print(f"{result:.2f}")

class RerankerBenchmark:
    def bi_encoder_rank(self, query: str, docs: list[str]) -> list[str]:
        q = set(query.lower().split())
        scored = [(len(q & set(d.lower().split())), d) for d in docs]
        # highest overlap first; equal overlaps are ordered by doc text, descending
        scored.sort(reverse=True)
        return [d for _, d in scored]

    def cross_encoder_score(self, query: str, doc: str) -> float:
        words = doc.lower().split()
        total = 0.0
        for w in query.lower().split():
            if w in words:
                total += 1.0 / (words.index(w) + 1)
        return total

    def _order_match(self, query: str, doc: str) -> int:
        q = query.lower().split()
        words = doc.lower().split()
        return sum(1 for i, w in enumerate(q) if i < len(words) and words[i] == w)

    def cross_encoder_rank(self, query: str, docs: list[str]) -> list[str]:
        # ties: prefer docs whose word order matches the query, then original order
        return sorted(
            docs,
            key=lambda d: (-round(self.cross_encoder_score(query, d), 9),
                           -self._order_match(query, d)),
        )

    def reciprocal_rank(self, ranked: list[str], relevant: set) -> float:
        for i, doc in enumerate(ranked, 1):
            if doc in relevant:
                return 1.0 / i
        return 0.0

    def compare(self, queries: list[str], corpus: list[str],
                relevant_labels: list[set]) -> dict:
        n = len(queries)
        if n == 0:
            return {"mrr_bi": 0.0, "mrr_ce": 0.0, "improvement": 0.0}
        bi_total = 0.0
        ce_total = 0.0
        for query, relevant in zip(queries, relevant_labels):
            bi_total += self.reciprocal_rank(self.bi_encoder_rank(query, corpus), relevant)
            ce_total += self.reciprocal_rank(self.cross_encoder_rank(query, corpus), relevant)
        mrr_bi = bi_total / n
        mrr_ce = ce_total / n
        return {"mrr_bi": mrr_bi, "mrr_ce": mrr_ce, "improvement": mrr_ce - mrr_bi}


bench = RerankerBenchmark()

print(f"{bench.cross_encoder_score('reset password', 'password reset steps'):.2f}")

bi = bench.bi_encoder_rank("reset password", [
    "account settings page",
    "password reset instructions",
    "reset your password now",
])
print(bi[0])

result = bench.compare(
    ["reset password", "login help"],
    ["password reset guide", "login assistance portal", "general faq"],
    [{"password reset guide"}, {"login assistance portal"}]
)
print(result["mrr_bi"] <= result["mrr_ce"])
